// Pega o que veio do nó anterior
const inputData = $input.all()[0].json; 

// O n8n às vezes aninha os dados. Vamos garantir que pegamos a lista.
let vagas = [];
if (Array.isArray(inputData)) {
    vagas = inputData; // Já é uma lista
} else if (inputData.body && Array.isArray(inputData.body)) {
    vagas = inputData.body; // A lista tá dentro de "body"
} else if (inputData.vagas && Array.isArray(inputData.vagas)) {
    vagas = inputData.vagas; // A lista tá dentro de "vagas"
} else {
    // Se não achou, tenta pegar o primeiro valor que for uma lista
    const chaves = Object.keys(inputData);
    for (let k of chaves) {
        if (Array.isArray(inputData[k])) {
            vagas = inputData[k];
            break;
        }
    }
}

// Se ainda não for uma lista, avisa
if (!Array.isArray(vagas)) {
    return [{ json: { texto: "Erro: Os dados recebidos da API não são uma lista válida.", total: 0 } }];
}

// Data de hoje e daqui a 7 dias
const hoje = new Date();
const daquiSeteDias = new Date();
daquiSeteDias.setDate(hoje.getDate() + 7);

// Filtra vagas com prazo entre hoje e daqui a 7 dias
const proximas = vagas.filter(v => {
    if (!v.vaga_prazo_final) return false; 
    const dataVaga = new Date(v.vaga_prazo_final + "T00:00:00");
    return dataVaga >= hoje && dataVaga <= daquiSeteDias;
});

// Se não tiver nada, avisa
if (proximas.length === 0) {
    return [{ json: { texto: "Nenhuma vaga com prazo nos próximos 7 dias.", total: 0 } }];
}

// Monta o texto para o Gemini
const texto = proximas.map(v => 
    `- ${v.emp_nome} (${v.vaga_area}): prazo ${v.vaga_prazo_final} | Link: ${v.vaga_link}`
).join('\n');

return [{ json: { texto: texto, total: proximas.length } }];

